MM.mnemo[5] = {"cards":[{"id":"ko-k3-0116","w":"쯤","cs":"asi, přibližně, kolem (za podstatným jménem)","en":"about, around (after a noun)","p":"o","o":"k","ex":"100명쯤 왔어요.","exc":"Přišlo asi sto lidí.","m":"Připojuje se bez mezery přímo za údaj o čase, množství nebo ceně (např. 내일쯤 = asi zítra, 두 시쯤 = kolem druhé). Má stejný význam jako 정도, ale píše se bez mezery."},{"id":"ko-k3-0117","w":"정도","cs":"asi, přibližně; míra, stupeň","en":"about, approximately (after a noun)","p":"n","o":"s","ex":"독일에서 2년 정도 살았어요.","exc":"Žil jsem v Německu asi dva roky. (에서 → kde se děj odehrává)","m":"程 míra + 度 stupeň = míra, přibližné množství. Na rozdíl od přípony 쯤 se píše s mezerou za číselným údajem (2년 정도) a dá se kombinovat i se slovem 약 na začátku (약 2년 정도).","r":["jeong-程","do-度"]},{"id":"ko-k3-0118","w":"약","cs":"asi, přibližně (před údajem); lék","en":"about (before a noun); medicine","p":"o","o":"s","ex":"약 한 달","exc":"asi jeden měsíc","m":"約 přibližně, zhruba = asi. Na rozdíl od 쯤 a 정도 stojí před číselným údajem (약 한 달 = asi měsíc) a často se s nimi spojuje pro zdůraznění (약 한 달 정도). Stejně zní i 약 (藥 = lék).","r":["yak-約"]},{"id":"ko-k3-0119","w":"한 시","cs":"jedna hodina (čas)","en":"1 o’clock","p":"f","o":"m","ex":"한 시쯤","exc":"kolem jedné hodiny","m":"Hodiny na ciferníku se v korejštině počítají ryze korejskými číslovkami, kde se 하나 před podstatným jménem zkracuje na 한 (한 시 = jedna hodina). Naopak minuty (분) používají číslovky sinokorejské.","r":["si-時"]},{"id":"ko-k3-0120","w":"천 원","cs":"tisíc wonů","en":"1,000 won","p":"f","o":"s","ex":"천 원쯤","exc":"asi tisíc wonů","m":"千 tisíc + 圓 won (korejská měna) = tisíc wonů. U číslovek 100 (백), 1 000 (천) a 10 000 (만) se v korejštině neříká ‚jedna‘ (일), takže ‚tisíc wonů‘ je jen 천 원.","r":["cheon-千","won-圓"]},{"id":"ko-k3-0121","w":"한 달","cs":"jeden měsíc (doba trvání)","en":"one month","p":"f","o":"k","ex":"약 한 달 정도","exc":"asi tak jeden měsíc","m":"Vyjadřuje délku trvání ‚jeden měsíc‘ (하나 se před 달 zkracuje na 한). Pozor na rozdíl oproti 일월 (leden, kalendářní měsíc); sinokorejský protějšek pro délku je 일 개월."},{"id":"ko-k3-0122","w":"킬로미터","cs":"kilometr","en":"kilometer","p":"n","o":"e","ex":"4킬로미터쯤","exc":"asi 4 kilometry","m":"Výpůjčka z anglického ‚kilometer‘. Čte se se sinokorejskými číslovkami (4킬로미터 = 사 킬로미터) a v hovoru se často zkracuje jen na 킬로."},{"id":"ko-k3-0123","w":"명","cs":"počitadlo pro osoby, lidí","en":"counter for people","p":"n","o":"s","ex":"도서관에 학생이 몇 명 있어요?","exc":"Kolik studentů je v knihovně? (에 → kde; 이 → 1. pád)","m":"名 jméno, osoba = počitadlo pro lidi, pojí se s ryze korejskými číslovkami (한 명 = jeden člověk, 두 명 = dva lidé). Zdvořilejší variantou pro starší či vážené osoby je 분.","r":["myeong-名"]},{"id":"ko-k3-0124","w":"마리","cs":"počitadlo pro zvířata, kusů (zvířat)","en":"counter for animals","p":"n","o":"k","ex":"고양이가 열 마리쯤 있어요.","exc":"Je tam asi deset koček. (가 → 1. pád)","m":"Počitadlo pro všechna zvířata od hmyzu přes psy až po ryby; pojí se s ryze korejskými číslovkami (고양이 한 마리 = jedna kočka, 강아지 두 마리 = dva pejsci)."},{"id":"ko-k3-0125","w":"병","cs":"počitadlo pro lahve, lahví","en":"counter for bottles","p":"n","o":"s","ex":"우유 열 병쯤 있어요.","exc":"Je tam asi deset lahví mléka.","m":"瓶 láhev = počitadlo pro lahve; pojí se s ryze korejskými číslovkami (물 한 병 = jedna láhev vody, 맥주 두 병 = dvě piva). Pozor na záměnu se stejným slovem 병 (病 = nemoc).","r":["byeong-瓶"]},{"id":"ko-k3-0128","w":"몇 시","cs":"kolik hodin (čas), v kolik","en":"what time","p":"f","o":"m","ex":"내일 몇 시쯤 만날까요?","exc":"Kolem kolikáté hodiny se zítra sejdeme? (-ㄹ까요 → návrh)","m":"Spojení tázacího slova 몇 (kolik) a kořene 時 (hodina) – ptá se na přesný čas na hodinách (지금 몇 시예요? = Kolik je teď hodin?). Na rozdíl od 몇 시간 (kolik hodin délky) nemá na konci 간.","r":["si-時"]},{"id":"ko-k3-0129","w":"어디쯤","cs":"kde asi, přibližně kde","en":"whereabouts","p":"o","o":"k","ex":"집이 어디쯤이에요?","exc":"Kde zhruba je tvůj dům? (이 → 1. pád)","m":"Spojení tázacího zájmena 어디 (kde) a přípony 쯤 (asi, přibližně). Používá se, když chceš vědět jen přibližnou polohu nebo čtvrť, ne přesnou adresu."},{"id":"ko-k3-0130","w":"저희","cs":"my, náš (skromně)","en":"we, us (humble)","p":"o","o":"k","ex":"저희는 지금 밥 먹을까요?","exc":"Máme se teď najíst? (는 → téma věty; -을까요 → návrh)","m":"Skromná (zdvořilá) obdoba zájmena 우리 (my), odvozená od 저 (já skromně). Používá se při mluvení se staršími, nadřízenými nebo cizími lidmi – nikdy ale mezi blízkými přáteli ani vůči mladším."},{"id":"ko-k3-0131","w":"현금","cs":"hotovost, hotové peníze","en":"cash","p":"n","o":"s","ex":"지금 현금 얼마 있어요?","exc":"Kolik máš teď u sebe hotovosti?","m":"現 současný, okamžitý + 金 peníze = peníze hned po ruce, tedy hotovost. Opakem platby v hotovosti (현금으로 내다) je platba kartou (카드로 내다).","r":["hyeon-現","geum-金"]},{"id":"ko-k3-0132","w":"도서관","cs":"knihovna","en":"library","p":"n","o":"s","ex":"도서관에 학생이 몇 명 있어요?","exc":"Kolik studentů je v knihovně? (에 → kde; 이 → 1. pád)","m":"圖 obraz, mapa + 書 kniha + 館 veřejná budova = budova plná knih a map, tedy knihovna. Kořen 書 znáš ze slova 서점 (knihkupectví) a 館 se objevuje u dalších institucí, třeba 박물관 (muzeum).","r":["do-圖","seo-書","gwan-館"]},{"id":"ko-k3-0134","w":"택배","cs":"zásilka, balík; doručování až domů","en":"delivery, parcel","p":"n","o":"s","ex":"택배는 두 시쯤에 올 거예요.","exc":"Balík přijde kolem druhé hodiny. (는 → téma věty; 에 → kdy)","m":"宅 dům, bydliště + 配 rozdělit, doručit = doručení přímo do domu, tedy balíková služba nebo samotný balík. Časté spojení: 택배를 보내다 / 받다 (poslat / dostat balík).","r":["taek-宅","bae-配"]}],"gram":{"id":"ko-k3-g05","w":"-쯤, 정도, 약","en":"Approximately, About","cs":"asi, přibližně, kolem","vy":"Všechny tři výrazy vyjadřují přibližný odhad množství, času nebo místa, ale liší se postavením. Přípona -쯤 se lepí bez mezery přímo za údaj, samostatné podstatné jméno 정도 stojí za údajem s mezerou a sinokorejské 약 (約) stojí naopak před ním. Pro zdůraznění se často kombinuje 약 před výrazem a 정도 za ním.","m":"Sendvič přibližnosti: 약 (約 přibližně) jde dopředu, 정도 (程度 stupeň/míra) dozadu s mezerou a krátké -쯤 se přilepí přímo na konec jako tečka.","s":[["100명쯤 왔어요.","Přišlo asi sto lidí."],["독일에서 2년쯤 살았어요.","Žil jsem v Německu asi dva roky."],["언제쯤 갈 거예요?","Kdy asi tak půjdeš?"],["내일 몇 시쯤 만날까요?","Kolem kolikáté se zítra sejdeme?"],["다섯 시쯤 어때요?","Co takhle kolem páté?"],["약 한 달 정도","přibližně asi jeden měsíc"],["현우 씨는 언제 와요?","Kdy přijde Hjonu?"],["밥 먹고 두 시쯤에 올 거예요.","Nají se a přijde kolem druhé."],["저희는 지금 밥 먹을까요?","Máme se teď najíst?"],["도서관에 학생이 몇 명 있어요?","Kolik studentů je v knihovně?"],["지금 현금 얼마 있어요?","Kolik máš teď u sebe hotovosti?"],["집이 어디쯤이에요?","Kde přibližně máš dům?"],["독일에서 2년 정도 살았어요.","Žil jsem v Německu přibližně dva roky."],["학생, 약 있어요?","Studente, máš u sebe nějaké léky?"],["택배는 두 시쯤에 올 거예요.","Balíček přijde kolem druhé hodiny."]]}};
